package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.os.*;
import android.provider.DocumentsContract;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** Physical input checks for desktop placement, taskbar toggling and Documents navigation. */
public class ContinuitySmoke extends Instrumentation {
    private MainActivity home;private View root;private DesktopStore store;private final Map<String,Object> originalSettings=new HashMap<>();
    private final BlockingQueue<MainActivity> resumed=new LinkedBlockingQueue<>();
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();Application app=(Application)getTargetContext().getApplicationContext();app.registerActivityLifecycleCallbacks(lifecycle);try{
        store=new DesktopStore(getTargetContext());for(String key:Arrays.asList("shortcuts","desktop_positions_portrait","desktop_positions_landscape","snap_desktop","layout_locked","reduce_motion"))originalSettings.put(key,store.prefs.getAll().get(key));store.desktop(Arrays.asList("@computer","@browser","@notes","@appearance"));store.prefs.edit().putBoolean("snap_desktop",true).putBoolean("layout_locked",false).putBoolean("reduce_motion",true).remove("desktop_positions_portrait").remove("desktop_positions_landscape").commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->find(v->v instanceof DesktopIconGrid)!=null,"Desktop ready");Thread.sleep(300);
        progress("real taskbar taps toggle the active window and raise a covered window");ui(()->home.open("@computer"));DesktopWindow computer=window("@computer");task("Minimize Computer");await(()->computer.getVisibility()==View.GONE,"Taskbar minimizes active folder");task("Restore Computer");await(()->computer.isShown()&&computer.active(),"Taskbar restores the same folder");ui(()->home.open("@notes"));DesktopWindow notes=window("@notes");task("Restore Computer");await(()->computer.active()&&notes.isShown(),"Covered folder comes to front without hiding other tools");task("Minimize Computer");await(()->!computer.isShown(),"Second tap minimizes foreground folder");ui(()->{notes.setVisibility(View.GONE);});
        progress("Start Documents and Computer Documents open the primary Documents directory");java.io.File documents=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOCUMENTS);check(documents.isDirectory()||documents.mkdirs(),"Documents directory exists");String name="Nth-Documents-"+SystemClock.uptimeMillis()+".txt";java.io.File probe=new java.io.File(documents,name);try(java.io.FileOutputStream out=new java.io.FileOutputStream(probe)){out.write("Documents path check".getBytes(java.nio.charset.StandardCharsets.UTF_8));}
        tap(find(v->"Start menu".equals(v.getContentDescription())));await(()->find(v->v instanceof StartMenu)!=null,"Start opened");View start=find(v->v instanceof StartMenu);tap(find(start,v->v instanceof TextView&&"Documents".contentEquals(((TextView)v).getText())));await(()->find(v->name.equals(v.getContentDescription()))!=null,"Start Documents contains file from physical Documents");VistaExplorer explorer=(VistaExplorer)window("@files").body;check("primary:Documents".equals(DocumentsContract.getDocumentId(DocumentOps.current(explorer.page()))),"Start opens primary Documents");ui(()->home.open("@computer"));View documentsRow=find(computer,v->"Documents".equals(v.getContentDescription()));tap(documentsRow);await(()->find(computer,v->name.equals(v.getContentDescription()))!=null,"Computer Documents reaches same real folder");probe.delete();
        ui(()->{for(int i=0;i<((ViewGroup)computer.getParent()).getChildCount();i++){View v=((ViewGroup)computer.getParent()).getChildAt(i);if(v instanceof DesktopWindow)v.setVisibility(View.GONE);}});
        progress("actual shortcut drag to blank space, setting checkbox and durable free positions");DesktopIconGrid grid=(DesktopIconGrid)find(v->v instanceof DesktopIconGrid);View icon=find(grid,v->"@computer".equals(v.getTag()));int[] location=new int[2];grid.getLocationOnScreen(location);float density=home.getResources().getDisplayMetrics().density;drag(icon,location[0]+Math.min(grid.getWidth()-20*density,135*density),location[1]+355*density);await(()->store.prefs.getString("desktop_positions_portrait","{}").contains("@computer"),"Blank desktop accepts shortcut drop");check(icon.getTop()>200*density,"Dropped shortcut actually moved into empty space");shot("desktop-snapped");ui(()->{home.open("@control");((VistaControlPanel)window("@control").body).navigate("taskbar");});CheckBox snap=(CheckBox)find(v->"Snap desktop apps to grid".equals(v.getContentDescription()));check(snap!=null&&snap.isChecked(),"Requested checkbox lives on Taskbar and Start Menu page");tap(snap);check(!store.prefs.getBoolean("snap_desktop",true),"Checkbox disables snapping");ui(()->window("@control").setVisibility(View.GONE));grid=(DesktopIconGrid)find(v->v instanceof DesktopIconGrid);icon=find(grid,v->"@computer".equals(v.getTag()));grid.getLocationOnScreen(location);float x=Math.min(grid.getWidth()-45*density,117*density),y=450*density;drag(icon,location[0]+x,location[1]+y);final View moved=icon;check(Math.abs(moved.getTop()/density/store.tileHeight()-Math.round(moved.getTop()/density/store.tileHeight()))>.08,"Free drop keeps a position between grid rows; actual top="+moved.getTop()/density);String positions=store.prefs.getString("desktop_positions_portrait","{}");float top=icon.getTop();shot("desktop-free");MainActivity before=home;resumed.clear();ui(home::recreate);long end=SystemClock.uptimeMillis()+12000;MainActivity next=null;while(SystemClock.uptimeMillis()<end){MainActivity candidate=resumed.poll(100,TimeUnit.MILLISECONDS);if(candidate!=null&&candidate!=before){next=candidate;break;}}check(next!=null,"Explicit recreation finished");home=next;root=home.getWindow().getDecorView();await(()->find(v->"@computer".equals(v.getTag()))!=null,"Desktop restored");await(()->{View restored=find(v->"@computer".equals(v.getTag()));return restored!=null&&Math.abs(restored.getTop()-top)<2;},"Free position survives Activity recreation after desktop rendering settles");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape settles");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getHeight()>root.getWidth(),"Portrait settles");check(positions.equals(store.prefs.getString("desktop_positions_portrait","{}")),"Landscape preserves separate portrait positions");DesktopBackup.Plan backup=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(backup.string("desktop_positions_portrait","{}").contains("@computer")&&Boolean.FALSE.equals(backup.values.get("snap_desktop")),"Validated backup includes positions and snap preference");
        result.putString("stream","PASS: physical taskbar taps minimize/restore/raise existing folder windows; Start and Computer Documents reach primary shared Documents and its actual files; physical shortcut drags to blank desktop work with snap on/off; requested settings checkbox updates snapping; free positions survive Activity recreation and both orientations; desktop positions and snap setting survive validated backups.\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("continuity-failure");}catch(Exception ignored){}StringWriter text=new StringWriter();failure.printStackTrace(new PrintWriter(text));result.putString("stream","FAIL: "+text);finish(Activity.RESULT_CANCELED,result);}finally{if(store!=null){android.content.SharedPreferences.Editor edit=store.prefs.edit();for(Map.Entry<String,Object> entry:originalSettings.entrySet()){Object value=entry.getValue();if(value==null)edit.remove(entry.getKey());else if(value instanceof String)edit.putString(entry.getKey(),(String)value);else if(value instanceof Boolean)edit.putBoolean(entry.getKey(),(Boolean)value);}edit.commit();}app.unregisterActivityLifecycleCallbacks(lifecycle);}}
    private DesktopWindow window(String id){return (DesktopWindow)find(v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void task(String label)throws Exception{View button=find(v->label.equals(v.getContentDescription()));check(button!=null,"Taskbar action exists: "+label);View ancestor=button;while(ancestor.getParent() instanceof View&&!(ancestor instanceof HorizontalScrollView))ancestor=(View)ancestor.getParent();check(ancestor instanceof HorizontalScrollView,"Taskbar scroll exists");HorizontalScrollView scroll=(HorizontalScrollView)ancestor;ui(()->{scroll.setSmoothScrollingEnabled(false);scroll.fullScroll(View.FOCUS_RIGHT);});getUiAutomation().waitForIdle(250,3000);tap(find(v->label.equals(v.getContentDescription())));}
    private void drag(View view,float x,float y)throws Exception{Rect bounds=new Rect();check(view!=null&&view.getGlobalVisibleRect(bounds),"Shortcut has visible drag bounds");float sx=bounds.exactCenterX(),sy=bounds.exactCenterY();long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,sx,sy);Thread.sleep(700);for(int i=1;i<=14;i++){input(down,MotionEvent.ACTION_MOVE,sx+(x-sx)*i/14,sy+(y-sy)*i/14);Thread.sleep(25);}input(down,MotionEvent.ACTION_UP,x,y);Thread.sleep(250);waitForIdleSync();}
    private void tap(View view)throws Exception{Rect rect=new Rect();check(view!=null&&view.isEnabled()&&view.getGlobalVisibleRect(rect),"Control has visible touch bounds");long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,rect.exactCenterX(),rect.exactCenterY());input(down,MotionEvent.ACTION_UP,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(200);}
    private void input(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"Touch accepted");e.recycle();}
    private View find(Predicate<View> test){return find(root,test);}private View find(View view,Predicate<View> test){if(view==null||!view.isShown())return null;if(test.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),test);if(found!=null)return found;}return null;}
    private void await(BooleanSupplier test,String message)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ok={false};runOnMainSync(()->ok[0]=test.getAsBoolean());if(ok[0])return;Thread.sleep(80);}throw new AssertionError(message);}
    private void ui(Runnable task){runOnMainSync(task);try{Thread.sleep(150);}catch(InterruptedException ex){throw new AssertionError(ex);}}
    private void shot(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot exists");try(FileOutputStream out=getTargetContext().openFileOutput(name+".png",0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}private void progress(String message){Bundle b=new Bundle();b.putString("stream","CHECK: "+message+"\n");sendStatus(1,b);}
}
